CraftingService.get_item_crafting_metadata = function (self, gear_id)
	return self._backend_interface.crafting:get_item_crafting_metadata(gear_id):next(function (result)
		return result
	end):catch(function (err)
		return Promise.rejected(err)
	end)
end

CraftingService.add_weapon_expertise = function (self, gear_id, added_expertise, costs)
	return self._backend_interface.crafting:add_weapon_expertise(gear_id, added_expertise):next(function (results)
		local item = results.items[1]
		local gear = item.gear

		Managers.data_service.gear:on_gear_updated(gear_id, gear)

		return Managers.data_service.store:on_crafting_done(costs):next(function ()
			return results
		end)
	end):catch(function (err)
		Managers.data_service.gear:invalidate_gear_cache()

Gear.fetch_by_id = function (self, account_id, gear_id)
	return BackendUtilities.make_account_title_request("account", BackendUtilities.url_builder("/gear/"):path(gear_id), {}, account_id):next(function (data)
		return data.body.gear
	end)
end

Gear.fetch_paged = function (self, size, slots)
	return Managers.backend:authenticate():next(function (account)
		local builder = BackendUtilities.url_builder():path("/v2/data/"):path(account.sub):path("/account/gear"):query("limit", size)

		if slots then
			builder:query("slots", slots)
		end

		return builder:to_string()
	end):next(function (path)
		return Managers.backend:title_request(path)
	end):next(function (data)
		return BackendUtilities.wrap_paged_response(data.body)
	end)
end

Gear.create = function (self, master_id, slot, character_id, overrides, allow_duplicate)
	return Managers.backend:authenticate():next(function (account)
		return string.format("/data/%s/account/gear?allowDuplicate=%s", account.sub, allow_duplicate)
	end):next(function (path)
		return Managers.backend:title_request(path, {
			method = "POST",
			body = {
				characterId = character_id,
				slots = type(slot) == "table" and slot or {
					slot,
				},
				masterDataInstance = {
					id = master_id,
					overrides = overrides,
				},
			},
		}):next(function (data)
			return data.body
		end)
	end)
end

Crafting.refresh_crafting_costs = function (self)
	return Managers.backend:title_request(BackendUtilities.url_builder("/data/account/crafting/costs"):to_string()):next(function (data)
		local weapon_crafting_costs = data.body.costs.weapon
		local gadget_crafting_costs = data.body.costs.gadget

		self._crafting_costs = {
			weapon = weapon_crafting_costs,
			gadget = gadget_crafting_costs,
		}

		return self._crafting_costs
	end)
end

Crafting.get_item_crafting_metadata = function (self, master_id)
	return Managers.backend:title_request(BackendUtilities.url_builder("/data/crafting/items/"):path(Http.url_encode(master_id)):path("/meta"):to_string()):next(function (data)
		return data.body
	end)
